def make_finding(item, number, refs):
    fid, name, primary_kind, required = item
    low = name.lower()
    kinds = [primary_kind, KINDS[(number + 4) % len(KINDS)], KINDS[(number + 9) % len(KINDS)]]
    questions = [
      {"id":f"{fid}-q01","text":f"What stable identities, classes, values and explicit unknowns establish {low}?","kind":kinds[0],"answer_data":["identities and classifications","declared values and states","explicit unknowns"]},
      {"id":f"{fid}-q02","text":f"Which authority, source, method, evidence, event time, knowledge time, confidence and limits support {low}?","kind":kinds[1],"answer_data":["authority and source","method and evidence","times, confidence and limits"]},
      {"id":f"{fid}-q03","text":f"How may {low} be validated, challenged, corrected, related, retained or disposed without losing history?","kind":kinds[2],"answer_data":["validation and challenge","correction and relationships","retention and disposition"]},
    ]
    return {"id":fid,"name":name,"description":f"Records {low} as source-qualified publication context while preserving external master ownership and separating instruction, delivery and observation.","source_refs":refs,"questions":questions,
      "data_elements":[{"id":f"{fid}-data","name":f"{name} data","description":f"Structured data for {low} with authority, time, state, evidence and access marking.","value_kind":"collection","cardinality":"1" if required else "0..n","required":required,"source_refs":refs}],
      "artifacts":[{"id":f"{fid}-record","name":f"{name} record","description":f"Versioned evidence-bearing publication record for {low}.","media_or_form":["logical publication assertion","instruction, decision, event, representation or evidence record"],"serial":True,"identity_strategy":f"Publication case ID plus {fid} assertion or event ID; title, date, URL and digest never identify the publication case alone.","source_refs":refs}],"inline_only_rationale":None}

def structure():
    bundles=[]; n=0
    for bid,bname,rationale,layers in ROWS:
        rendered=[]
        for lid,lname,refs,findings in layers:
            values=[]
            for finding in findings:
                n += 1; values.append(make_finding(finding,n,refs))
            rendered.append({"id":lid,"name":lname,"description":f"Groups publication context for {lname.lower()}.","source_refs":refs,"findings":values})
        bundles.append({"id":bid,"name":bname,"description":f"Groups governed context for {bname.lower()}.","rationale":rationale+".","source_refs":sorted({ref for layer in layers for ref in layer[2]}),"layers":rendered})
    return {"bundles":bundles}

