def coverage():
    dimensions=["identity","classification and definition","direct properties","recognition and observation","capabilities and possible actions","composition","lifecycle","relationships","temporal","spatial","provenance","ownership and stewardship","validation and quality","access and privacy","retention and deletion","interoperability"]
    gaps={"direct properties","spatial"}
    return {"claim":"Covers one governed content-publication case from intake and review through instruction, distribution, observation, correction and disposition.","confidence":"medium","checklist":[{"dimension":d,"status":"gap" if d in gaps else "covered","notes":f"{d.capitalize()} is explicit; external masters, platform profiles and unresolved candidate relations remain held where applicable."} for d in dimensions],
      "known_omissions":["Claude and Grok each timed out on one bounded attempt; no independent external result was admitted.","The Publication / Edition parent is candidate registry metadata, not an approved relation edge.","Platform-specific APIs, newsroom standards, scholarly publishing rules, app-store workflows and jurisdictional notice duties require separate profiles.","Sitemaps describe discovery hints and do not prove crawling, indexing, ranking or public reach."],
      "conflicts":["Editorial approval, rights clearance, release instruction, successful delivery and public availability are not interchangeable.","A content resource, edition, revision, representation, rendition, canonical URI and delivery URL can overlap but retain different identity and lifecycle rules.","Correction, update, retraction, withdrawal, takedown, unpublish, tombstone and erasure have different authority and preservation effects."],
      "regional_assumptions":["Copyright, privacy, accessibility, retention and takedown duties depend on jurisdiction, audience and channel.","Platform acceptance and HTTP success do not establish legal publication or audience receipt.","Required notices, preservation periods and correction practices vary by sector."],
      "adversarial_checks":["Reject a case without stable identity, target revision, owner, mandate, profile and lineage head.","Reject approval represented as public availability, an HTTP acknowledgement represented as audience reach, or syndication represented as authoritative origin publication.","Reject silent overwrite of decisions, instructions, evidence, corrections or retractions.","Reject autonomous publication, protected disclosure, rights waiver, takedown or disposal outside delegated authority.","Reject timestamps without seconds and an explicit RFC 3339 offset."]}

